static size_t split(char *buffer,int script){char *r=buffer,*w=buffer;size_t count=0;while(*r){int at=0;while(*r==' '||*r=='\n')++r;if(!*r)break;if(script&&count==1&&*r=='@'){at=1;++r;}if(*r++!='"')fail("original FmtShell quoting");if(count==WORDS)fail("argument bound");words[count++]=w;if(at)*w++='@';while(*r&&*r!='"'){unsigned char c=(unsigned char)*r++;if(c=='\\'){c=(unsigned char)*r++;if(c!='\\'&&c!='"'&&c!=' ')fail("original FmtShell escape");}if(script&&(c<32||c==127||strchr("$`;&|<>()",c)))fail("original FmtShell control/operator");*w++=(char)c;}if(*r++!='"')fail("unterminated original quoting");if(*r&&*r!=' '&&*r!='\n')fail("original command operator");while(*r==' '||*r=='\n')++r;*w++=0;}return count;}
