static char *relocate_from(const char *word,const char *old,const char *destination){size_t n=strlen(old),m=strlen(destination),count=0;const char *p=word,*at;while((at=strstr(p,old))){if(at[n]&&at[n]!='/')fail("ambiguous generated path prefix");++count;p=at+n;}size_t size=strlen(word);if(size>BOUND)fail("relocated word bound");if(m>n){if(count>(BOUND-size)/(m-n))fail("relocated word bound");size+=count*(m-n);}else size-=count*(n-m);char *result=memory(size+1),*out=result;p=word;while((at=strstr(p,old))){size_t before=(size_t)(at-p);memcpy(out,p,before);out+=before;memcpy(out,destination,m);out+=m;p=at+n;}strcpy(out,p);return result;}
static char *relocate(const char *word,const char *destination){return relocate_from(word,"/outputs/translation",destination);}
static void net(FILE *f,const char *value,size_t size){if(fprintf(f,"%zu:",size)<0||(size&&fwrite(value,1,size,f)!=size)||fputc(',',f)==EOF)fail("environment frame");}
