static int metadata_kind(const char *kind){return !strcmp(kind,"rlib")||!strcmp(kind,"proc-macro");}
static void kind(const char *value){if(strcmp(value,"rlib")&&strcmp(value,"bin")&&strcmp(value,"proc-macro")&&strcmp(value,"dylib")&&strcmp(value,"build-script"))fail("crate kind");}
