 char *name=suffix(base,"-codegen.sh"),*original=join(root,name);load(original,command);size_t count=split(command,1);char *response=suffix(base,"_cmd.txt"),*expected_response=join("/outputs/translation",response);if(count!=2||strcmp(words[0],argv[5])||words[1][0]!='@'||strcmp(words[1]+1,expected_response))fail("original exact deferred compiler/response");file(original,argv[11],0);free(original);
